typedef struct {uint8_t type,data[64];size_t n;} message;
typedef struct endpoint endpoint;
struct endpoint {l2_core_t core;l2_peer_machine_t machine;endpoint *other;message queue[1024];unsigned count,writes,sends,drops;int drop_type;bool fail;uint8_t blob[L2_STORE_MAX];size_t blob_size;};
static endpoint a,b;static uint32_t clock_ms;
static bool persist(void *ctx,const uint8_t *data,size_t n){endpoint *e=ctx;e->writes++;if(e->fail)return false;assert(n<=sizeof(e->blob));memcpy(e->blob,data,n);e->blob_size=n;return true;}
static bool send_message(void *ctx,uint8_t type,const uint8_t *data,size_t n){endpoint *e=ctx;e->sends++;if(type==L2P_MSG_GIFT){bool durable=false;for(unsigned i=0;i<e->core.saved.peer_count;i++)if(!strcmp(e->core.saved.peers[i].peer_id,e->machine.view.peer_id)&&e->core.saved.peer_first_outgoing[i]==e->machine.outgoing.counter)durable=true;assert(durable);}if(e->drop_type==type&&e->drops){e->drops--;return true;}assert(e->other->count<1024);message *m=&e->other->queue[e->other->count++];m->type=type;m->n=n;memcpy(m->data,data,n);return true;}
static void fresh(void){clock_ms=0;memset(&a,0,sizeof(a));memset(&b,0,sizeof(b));a.other=&b;b.other=&a;assert(l2_init_new(&a.core,"11111111111111111111111111111111",persist,&a)==L2_OK);assert(l2_init_new(&b.core,"22222222222222222222222222222222",persist,&b)==L2_OK);assert(l2_peer_machine_init(&a.machine,&a.core,send_message,&a));assert(l2_peer_machine_init(&b.machine,&b.core,send_message,&b));}
static void link_pair(void){uint8_t na[16]={3},nb[16]={4};assert(l2_peer_machine_enable(&a.machine,true,na));assert(l2_peer_machine_enable(&b.machine,true,nb));l2_peer_machine_link(&a.machine,true,b.machine.own_id,nb);l2_peer_machine_link(&b.machine,true,a.machine.own_id,na);}
static void drain(endpoint *e){unsigned n=e->count;e->count=0;for(unsigned i=0;i<n;i++)(void)l2_peer_machine_receive(&e->machine,e->queue[i].type,e->queue[i].data,e->queue[i].n);}
static void pump(unsigned rounds,bool ca,bool cb){for(unsigned i=1;i<=rounds;i++){drain(&a);drain(&b);if(ca&&a.machine.hello_seen&&!a.machine.view.local_confirmed)(void)l2_peer_machine_confirm(&a.machine);if(cb&&b.machine.hello_seen&&!b.machine.view.local_confirmed)(void)l2_peer_machine_confirm(&b.machine);clock_ms+=100;l2_peer_machine_poll(&a.machine,clock_ms);l2_peer_machine_poll(&b.machine,clock_ms);}}
static void complete(void){assert(a.machine.view.complete&&b.machine.view.complete);assert(a.machine.view.complete_count==1&&b.machine.view.complete_count==1);assert(a.core.saved.event_count==1&&b.core.saved.event_count==1);assert(a.core.saved.outgoing_count==0&&b.core.saved.outgoing_count==0);}
