 const int types[]={L2P_MSG_HELLO,L2P_MSG_CONFIRM,L2P_MSG_GIFT,L2P_MSG_ACK,L2P_MSG_DONE};for(unsigned i=0;i<5;i++){fresh();link_pair();a.drop_type=types[i];a.drops=1;pump(800,true,true);complete();}puts("PASS first HELLO/CONFIRM/GIFT/ACK/DONE drop retries");
 fresh();link_pair();pump(50,false,false);uint8_t bad[64]={0};assert(!l2_peer_machine_receive(&a.machine,L2P_MSG_CONFIRM,bad,32));assert(!l2_peer_machine_receive(&a.machine,L2P_MSG_GIFT,bad,45));assert(!l2_peer_machine_receive(&a.machine,L2P_MSG_HELLO,bad,37));puts("PASS nonce, identity and pre-confirm rejection");
 fresh();link_pair();pump(20,true,false);l2_peer_machine_link(&a.machine,false,NULL,NULL);pump(100,true,true);assert(!a.machine.view.complete&&!b.machine.view.complete);assert(!a.core.saved.event_count&&!b.core.saved.event_count);puts("PASS interrupted confirmation never completes");
 fresh();link_pair();a.fail=true;pump(200,true,true);assert(a.machine.view.phase==L2P_BLOCKED&&a.machine.view.storage_status==L2_STORAGE_ERROR);assert(!a.machine.view.complete&&!b.machine.view.complete);assert(!a.core.saved.event_count);puts("PASS durable reserve failure cannot send success");
 fresh();l2_receipt_t reserved;assert(l2_peer_reserve_gift(&a.core,"22222222222222222222222222222222",L2_GIFT_FLOWER,1,&reserved)==L2_OK);uint64_t counter=reserved.counter;assert(l2_load(&a.core,a.blob,a.blob_size,persist,&a)==L2_OK);assert(l2_peer_machine_init(&a.machine,&a.core,send_message,&a));link_pair();pump(500,true,true);complete();assert(a.machine.outgoing.counter==counter&&a.core.saved.next_peer_counter==counter+1);puts("PASS restart reuses pending durable outbox counter");
 fresh();assert(l2_peer_reserve_gift(&a.core,"33333333333333333333333333333333",L2_GIFT_FLOWER,1,&reserved)==L2_OK);link_pair();pump(200,true,true);assert(a.machine.view.complete&&b.machine.view.complete);assert(a.core.saved.outgoing_count==1&&a.core.saved.outgoing[0].counter==reserved.counter);assert(a.core.saved.event_count==1&&b.core.saved.event_count==1);puts("PASS unrelated durable pending peer does not block current peer receipt");
 fresh();link_pair();pump(20,false,false);assert(l2_peer_machine_confirm(&a.machine));assert(l2_peer_machine_confirm(&b.machine));a.machine.view.remote_confirmed=true;a.fail=true;uint8_t gift[45]={1};gift[8]=L2_GIFT_FLOWER;gift[9]=1;memcpy(gift+13,b.machine.nonce,16);memcpy(gift+29,a.machine.nonce,16);assert(!l2_peer_machine_receive(&a.machine,L2P_MSG_GIFT,gift,45));assert(!a.machine.view.incoming_saved&&!a.machine.ack_pending&&!a.machine.view.complete);puts("PASS incoming persist failure never ACKs receipt");
 fresh();for(unsigned i=0;i<L2_PEER_MAX;i++){l2_receipt_t r={.counter=1,.gift_kind=L2_GIFT_FLOWER,.quantity=1};snprintf(r.peer_id,sizeof(r.peer_id),"%032x",i+3);assert(l2_receive_gift(&a.core,&r)==L2_OK);}link_pair();pump(300,true,true);assert(a.machine.view.phase==L2P_BLOCKED&&a.machine.view.storage_status==L2_PEER_FULL);assert(!a.machine.view.incoming_saved&&!a.machine.view.complete);puts("PASS 32 peer watermark limit refuses unknown peer");
 fresh();l2_snapshot_t snapshot={0};strcpy(snapshot.pet.pet_id,"test-pet");strcpy(snapshot.pet.name,"cat");strcpy(snapshot.pet.breed,"orange");l2_request_t request={.seq=1};strcpy(request.client_id,"11111111-1111-1111-1111-111111111111");strcpy(request.request_id,"setup");assert(l2_set_snapshot(&a.core,&request,&snapshot)==L2_OK);for(unsigned i=0;i<L2_EVENT_MAX;i++)assert(l2_emit_care(&a.core,L2_ACTION_PET,0)==L2_OK);l2_receipt_t full={.counter=1,.gift_kind=L2_GIFT_FLOWER,.quantity=1};strcpy(full.peer_id,"22222222222222222222222222222222");assert(l2_receive_gift(&a.core,&full)==L2_QUEUE_FULL);assert(a.core.saved.peer_count==0);puts("PASS full durable event FIFO rejects without advancing watermark");
 fresh();link_pair();a.drop_type=b.drop_type=L2P_MSG_DONE;a.drops=b.drops=10000;pump(100,true,true);assert(a.machine.view.incoming_saved&&b.machine.view.incoming_saved&&a.machine.view.outgoing_acked&&b.machine.view.outgoing_acked);assert(!a.machine.view.complete&&!b.machine.view.complete);uint64_t ac=a.core.saved.next_peer_counter,bc=b.core.saved.next_peer_counter;assert(l2_load(&a.core,a.blob,a.blob_size,persist,&a)==L2_OK);assert(l2_load(&b.core,b.blob,b.blob_size,persist,&b)==L2_OK);a.count=b.count=0;a.drop_type=b.drop_type=0;assert(l2_peer_machine_init(&a.machine,&a.core,send_message,&a));assert(l2_peer_machine_init(&b.machine,&b.core,send_message,&b));uint8_t na[16]={7},nb[16]={8};assert(l2_peer_machine_enable(&a.machine,true,na));assert(l2_peer_machine_enable(&b.machine,true,nb));l2_peer_machine_link(&a.machine,true,b.machine.own_id,nb);l2_peer_machine_link(&b.machine,true,a.machine.own_id,na);pump(100,false,false);assert(!a.machine.view.complete&&!b.machine.view.complete);pump(500,true,true);complete();assert(!a.machine.view.incoming_new&&!b.machine.view.incoming_new);assert(a.core.saved.next_peer_counter==ac&&b.core.saved.next_peer_counter==bc);puts("PASS lost DONE, both reboot, new nonce + new physical consent: no second first-gift event");
 return 0;
